#!/usr/bin/env node
// Turns the module map (docs/architecture/modules.json) into enforceable rules and diagrams.
//
//   node scripts/dsf/arch/modules.mjs gen      write docs/architecture/generated/*
//   node scripts/dsf/arch/modules.mjs --check  fail when the generated files are out of date
//
// modules.json:
// { "modules": [
//     { "name": "core", "path": "src/core", "responsibility": "Domain rules", "publicApi": "src/core/index.ts", "dependsOn": [] },
//     { "name": "ui",   "path": "src/ui",   "responsibility": "Screens",      "publicApi": "src/ui/index.ts",   "dependsOn": ["core"] } ] }
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
const mapFile = join(root, "docs", "architecture", "modules.json");
const outDir = join(root, "docs", "architecture", "generated");

if (!existsSync(mapFile)) {
  console.log("No docs/architecture/modules.json yet; the architect agent creates it (skill dsf-architect).");
  process.exit(0);
}
const { modules = [] } = JSON.parse(readFileSync(mapFile, "utf8"));
const names = new Set(modules.map((m) => m.name));
const problems = [];
for (const m of modules) {
  if (!m.name || !m.path) problems.push(`module without name or path: ${JSON.stringify(m)}`);
  for (const d of m.dependsOn || []) if (!names.has(d)) problems.push(`${m.name} depends on unknown module '${d}'`);
}
if (problems.length) {
  console.error(problems.join("\n"));
  process.exit(1);
}

const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const id = (s) => s.replace(/[^A-Za-z0-9_]/g, "_");

// dependency-cruiser rules: only declared dependencies, and only through the public API.
const rules = [];
for (const m of modules) {
  const allowed = new Set([m.name, ...(m.dependsOn || [])]);
  const forbidden = modules.filter((o) => !allowed.has(o.name));
  if (forbidden.length) {
    rules.push({
      name: `dsf-module-${m.name}-undeclared-dependency`,
      comment: `${m.name} may only depend on: ${[...(m.dependsOn || [])].join(", ") || "nothing"} (docs/architecture/modules.json)`,
      severity: "error",
      from: { path: `^${esc(m.path)}/` },
      to: { path: `^(${forbidden.map((o) => esc(o.path)).join("|")})/` },
    });
  }
  if (m.publicApi) {
    rules.push({
      name: `dsf-module-${m.name}-private-access`,
      comment: `Other modules must import ${m.name} only through ${m.publicApi}`,
      severity: "error",
      from: { pathNot: `^${esc(m.path)}/` },
      to: { path: `^${esc(m.path)}/`, pathNot: `^${esc(m.publicApi)}$` },
    });
  }
}
const rulesJs =
  "// Generated by scripts/dsf/arch/modules.mjs from docs/architecture/modules.json. Do not edit.\n" +
  `module.exports = ${JSON.stringify(rules, null, 2)};\n`;

// Coupling view: the intended dependencies between modules.
const coupling = [
  "%% Generated from docs/architecture/modules.json. Intended dependencies between modules.",
  "flowchart LR",
  ...modules.map((m) => `  ${id(m.name)}["${m.name}"]`),
  ...modules.flatMap((m) => (m.dependsOn || []).map((d) => `  ${id(m.name)} --> ${id(d)}`)),
].join("\n") + "\n";

// Cohesion view: what each module is responsible for, and its public API.
const cohesion = [
  "%% Generated from docs/architecture/modules.json. One box per module with its single responsibility.",
  "flowchart TB",
  ...modules.flatMap((m) => [
    `  subgraph ${id(m.name)}["${m.name}"]`,
    `    ${id(m.name)}_r["${(m.responsibility || "responsibility not stated").replaceAll('"', "'")}"]`,
    ...(m.publicApi ? [`    ${id(m.name)}_api(["public API: ${m.publicApi}"])`] : []),
    "  end",
  ]),
].join("\n") + "\n";

const files = {
  "depcruise-modules.cjs": rulesJs,
  "modules-coupling.mmd": coupling,
  "modules-cohesion.mmd": cohesion,
};

if (process.argv.includes("--check")) {
  const stale = Object.entries(files).filter(([f, text]) => {
    const p = join(outDir, f);
    return !existsSync(p) || readFileSync(p, "utf8") !== text;
  });
  if (stale.length) {
    console.error(`Out of date: ${stale.map(([f]) => `docs/architecture/generated/${f}`).join(", ")}. Run 'make arch-rules' (design mode).`);
    process.exit(1);
  }
  process.exit(0);
}
mkdirSync(outDir, { recursive: true });
for (const [f, text] of Object.entries(files)) writeFileSync(join(outDir, f), text);
console.log(`Wrote ${Object.keys(files).length} files to docs/architecture/generated/ for ${modules.length} modules.`);
